/**
 * The positional-ref stability guard (Wave 1 stage 0, task K1-1): the committed snapshot of every stored-answer ref and
 * its fingerprint, the allowlist that makes a re-point explicit, and the two migration tables pinned empty.
 *
 * The baseline is generated by `bun scripts/snapshot-refs.ts`. A content PR may run the writer to add the refs it
 * creates; it may not use it to silence a re-point. A changed or missing ref needs a one-shot row in
 * `tests/fixtures/ref-allow.json` (a rewrite names the fingerprint it accepts; a move names the new ref), so the
 * reviewer sees exactly which stored answers the PR re-points.
 */
import { describe, expect, test } from 'bun:test'
import { readFileSync } from 'node:fs'
import path from 'node:path'
import type { QuizQuestion } from '../../src/components/QuizBlock'
import { KC_MIGRATIONS } from '../../src/data/kc/migrations'
import { ALL_LESSONS } from '../../src/data/lessons'
import type { Lesson } from '../../src/data/lessons/types'
import { R_ANCHORS } from '../../src/data/placement/anchors'
import { revFor } from '../../src/lib/items/play'
import { authoredItemRev, constructedRev, diagramPredictRev, prequestionRev, quizRev } from '../../src/lib/kc/resolve'
import { breakItem } from '../../src/lib/learner/iso'
import { PROTEGE_STEPS, stepItem } from '../../src/lib/learner/protege'
import { activePredict, diaRef, preRef } from '../../src/lib/learner/prequestions'
import { REF_MIGRATIONS } from '../../src/lib/ledger/refs'
import { compareRefs, collectRefs, serialize, type RefAllow, type RefEntry } from '../../scripts/snapshot-refs'

const FIXTURES = path.resolve(import.meta.dir, '../fixtures')
const BASELINE = (JSON.parse(readFileSync(path.join(FIXTURES, 'ref-revs.json'), 'utf8')) as { refs: RefEntry[] }).refs
const ALLOW = JSON.parse(readFileSync(path.join(FIXTURES, 'ref-allow.json'), 'utf8')) as RefAllow[]

type QuizBlock = Extract<Lesson['blocks'][number], { type: 'quiz' }>
type PredictBlock = Extract<Lesson['blocks'][number], { type: 'predict' }>
type CodeBlock = Extract<Lesson['blocks'][number], { type: 'code' }>

const cloneLessons = (): Lesson[] => structuredClone(ALL_LESSONS) as Lesson[]

const quizAt = (lessons: readonly Lesson[]): { lesson: Lesson; block: QuizBlock } => {
  for (const lesson of lessons) {
    for (const block of lesson.blocks) if (block.type === 'quiz') return { lesson, block }
  }
  throw new Error('no quiz block')
}

const predictAt = (lessons: readonly Lesson[]): { lesson: Lesson; index: number; block: PredictBlock } => {
  for (const lesson of lessons) {
    for (const [index, block] of lesson.blocks.entries()) if (block.type === 'predict') return { lesson, index, block }
  }
  throw new Error('no predict block')
}

const codeAlignAt = (lessons: readonly Lesson[]): { lesson: Lesson; n: number; block: CodeBlock; q: QuizQuestion } => {
  for (const lesson of lessons) {
    let n = 0
    for (const block of lesson.blocks) {
      if (block.type !== 'code' || !block.align) continue
      for (const q of block.align) {
        n += 1
        return { lesson, n, block, q }
      }
    }
  }
  throw new Error('no alignment item')
}

const secondAlign = (lessons: readonly Lesson[]): { lesson: Lesson; n: number; q: QuizQuestion } => {
  for (const lesson of lessons) {
    const items: QuizQuestion[] = []
    for (const block of lesson.blocks) if (block.type === 'code' && block.align) items.push(...block.align)
    if (items.length >= 2) return { lesson, n: 2, q: items[1] }
  }
  throw new Error('no lesson with two alignment items')
}

const refsOf = (findings: readonly { ref: string }[]): string[] => findings.map((f) => f.ref).sort()

const allow = (entry: Partial<RefAllow> & Pick<RefAllow, 'ref' | 'reason'>): RefAllow => entry

describe('the snapshot', () => {
  test('the tree matches the committed baseline and the allowlist, so bun test passes at the base', () => {
    expect(compareRefs(BASELINE, collectRefs(), ALLOW)).toEqual([])
  })

  test('the committed file is byte-for-byte what the writer produces, in collection order', () => {
    expect(readFileSync(path.join(FIXTURES, 'ref-revs.json'), 'utf8')).toBe(serialize(collectRefs()))
  })

  test('the collector is deterministic and a ref is never defined twice', () => {
    expect(collectRefs()).toEqual(collectRefs())
    expect(new Set(BASELINE.map((e) => e.ref)).size).toBe(BASELINE.length)
    const lesson = ALL_LESSONS[0]
    expect(() => collectRefs([lesson, lesson])).toThrow(/duplicate ref/)
  })

  test('the baseline covers every kind of stored answer the lessons write', () => {
    const refs = new Set(collectRefs().map((e) => e.ref))
    const has = (pattern: RegExp): boolean => [...refs].some((r) => pattern.test(r))
    expect(has(/^quiz:/)).toBe(true)
    expect(has(/^pre:/)).toBe(true)
    expect(has(/^dia:/)).toBe(true)
    expect(has(/^cr:/)).toBe(true)
    expect(has(/^item:.+\.align\.\d+$/)).toBe(true)
    expect(has(/^item:.+\.iso\.\d+$/)).toBe(true)
    expect(has(/^item:.+\.iso\.\d+\.break$/)).toBe(true)
    expect(has(/^item:.+\.protege\.\d+\.find$/)).toBe(true)
    expect(has(/^item:.+\.spiral\./)).toBe(true)
    expect(has(/^item:r\.anchor\./)).toBe(true)
  })
})

describe('a stored answer that moves', () => {
  test('changing one option of a quiz question fails, naming that quiz ref', () => {
    const lessons = cloneLessons()
    const { lesson, block } = quizAt(lessons)
    const ref = `quiz:${lesson.id}#0`
    block.questions[0].options[0] = `${block.questions[0].options[0]} (changed)`

    const findings = compareRefs(BASELINE, collectRefs(lessons), [])
    expect(findings).toContainEqual(expect.objectContaining({ ref, kind: 'changed' }))
    expect(findings).toHaveLength(1)
  })

  test('appending a question passes: a new ref is content, not a re-point', () => {
    const lessons = cloneLessons()
    const { block } = quizAt(lessons)
    block.questions.push(structuredClone(block.questions[0]))

    expect(compareRefs(BASELINE, collectRefs(lessons), [])).toEqual([])
  })

  test('inserting a predict item before the others fails, naming every shifted pre: ref', () => {
    const lessons = cloneLessons()
    const { lesson, block } = predictAt(lessons)
    const inserted = structuredClone(block.items[0])
    inserted.q = `inserted: ${inserted.q}`
    block.items.unshift(inserted)

    const before = collectRefs().filter((e) => e.ref.startsWith(`pre:${lesson.id}#`))
    const findings = compareRefs(BASELINE, collectRefs(lessons), [])
    expect(refsOf(findings)).toEqual(before.map((e) => e.ref).sort())
    for (const finding of findings) expect(finding.kind).toBe('changed')
  })

  test('a second predict block would write the same refs, so the collector refuses rather than renumbers', () => {
    const lessons = cloneLessons()
    const { lesson, index, block } = predictAt(lessons)
    const second = structuredClone(block)
    second.items.forEach((item, i) => {
      item.q = `second ${i}: ${item.q}`
    })
    lesson.blocks.splice(index + 1, 0, second)

    expect(() => collectRefs(lessons)).toThrow(/duplicate ref pre:/)
  })
})

describe('the allowlist', () => {
  const base: RefEntry[] = [
    { ref: 'quiz:a#0', rev: 'one' },
    { ref: 'quiz:a#1', rev: 'two' },
  ]
  const current: RefEntry[] = [
    { ref: 'quiz:a#0', rev: 'one' },
    { ref: 'quiz:a#2', rev: 'three' },
  ]

  test('a rewrite passes only with the fingerprint it accepts, and the same row cannot excuse a later change', () => {
    expect(compareRefs(base, current, [allow({ ref: 'quiz:a#1', reason: 'moved', to: 'quiz:a#2' })])).toEqual([])

    const changed = [{ ref: 'quiz:a#0', rev: 'one' }, { ref: 'quiz:a#1', rev: 'changed' }]
    expect(compareRefs(base, changed, [allow({ ref: 'quiz:a#1', reason: 'rewritten', rev: 'changed' })])).toEqual([])
    expect(compareRefs(base, changed, [allow({ ref: 'quiz:a#1', reason: 'rewritten', rev: 'other' })])).toContainEqual(
      expect.objectContaining({ ref: 'quiz:a#1', kind: 'changed' }),
    )
    const noRev = compareRefs(base, changed, [allow({ ref: 'quiz:a#1', reason: 'rewritten' })])
    expect(noRev.map((f) => f.kind)).toEqual(['malformed'])
    const later = [{ ref: 'quiz:a#0', rev: 'one' }, { ref: 'quiz:a#1', rev: 'changed again' }]
    expect(compareRefs(base, later, [allow({ ref: 'quiz:a#1', reason: 'rewritten', rev: 'changed' })])).toContainEqual(
      expect.objectContaining({ ref: 'quiz:a#1', kind: 'changed' }),
    )
  })

  test('a move needs a new ref the tree writes; a rewrite cannot excuse a missing ref', () => {
    const rewritten = [
      { ref: 'quiz:a#0', rev: 'one' },
      { ref: 'quiz:a#1', rev: 'changed' },
    ]
    expect(compareRefs(base, current, [allow({ ref: 'quiz:a#1', reason: 'reindexed', to: 'quiz:a#2' })])).toEqual([])
    expect(compareRefs(base, current, [allow({ ref: 'quiz:a#1', reason: 'rewritten', rev: 'x' })])).toContainEqual(
      expect.objectContaining({ ref: 'quiz:a#1', kind: 'missing' }),
    )
    expect(compareRefs(base, current, [allow({ ref: 'quiz:a#1', reason: 'moved', to: 'quiz:a#0' })])).toContainEqual(
      expect.objectContaining({ ref: 'quiz:a#1', kind: 'malformed' }),
    )
    expect(compareRefs(base, current, [allow({ ref: 'quiz:a#1', reason: 'moved', to: 'quiz:no.such#9' })])).toContainEqual(
      expect.objectContaining({ ref: 'quiz:a#1', kind: 'malformed' }),
    )
    expect(compareRefs(base, current, [allow({ ref: 'quiz:a#1', reason: 'moved' })])).toContainEqual(
      expect.objectContaining({ ref: 'quiz:a#1', kind: 'malformed' }),
    )
    expect(compareRefs(base, rewritten, [allow({ ref: 'quiz:a#1', reason: 'moved', to: 'quiz:a#2' })])).toContainEqual(
      expect.objectContaining({ ref: 'quiz:a#1', kind: 'malformed' }),
    )
  })

  test('the list may not carry noise: a stale row, an unknown ref or a bad reason fails', () => {
    expect(compareRefs(base, base, [allow({ ref: 'quiz:a#0', reason: 'rewritten', rev: 'one' })])).toContainEqual(
      expect.objectContaining({ ref: 'quiz:a#0', kind: 'stale' }),
    )
    expect(compareRefs(base, base, [allow({ ref: 'quiz:no.such#0', reason: 'rewritten', rev: 'x' })])).toContainEqual(
      expect.objectContaining({ ref: 'quiz:no.such#0', kind: 'unknown' }),
    )
    expect(compareRefs(base, base, [allow({ ref: 'quiz:a#0', reason: 'renamed' as RefAllow['reason'], rev: 'x' })])).toContainEqual(
      expect.objectContaining({ ref: 'quiz:a#0', kind: 'malformed' }),
    )
    expect(compareRefs(base, base, [allow({ ref: 'quiz:a#0', reason: 'rewritten', rev: 'one' }), allow({ ref: 'quiz:a#0', reason: 'rewritten', rev: 'one' })])).toContainEqual(
      expect.objectContaining({ ref: 'quiz:a#0', kind: 'duplicate' }),
    )
  })
})

describe('the fingerprints are the writers\' own', () => {
  test('a quiz question, a prequestion, a gated diagram and a constructed response carry their writer\'s fingerprint', () => {
    const quiz = quizAt(ALL_LESSONS)
    expect(BASELINE).toContainEqual({ ref: `quiz:${quiz.lesson.id}#0`, rev: quizRev(quiz.block.questions[0]) })

    const pre = predictAt(ALL_LESSONS)
    expect(BASELINE).toContainEqual({ ref: preRef(pre.lesson.id, 0), rev: prequestionRev(pre.block.items[0]) })

    for (const lesson of ALL_LESSONS) {
      let found = false
      lesson.blocks.forEach((block, bi) => {
        const d = block.type === 'diagram' ? activePredict(block) : null
        if (d && !found) {
          found = true
          expect(BASELINE).toContainEqual({ ref: diaRef(lesson.id, bi), rev: diagramPredictRev(d) })
        }
      })
      if (found) break
    }

    for (const lesson of ALL_LESSONS) {
      const c = lesson.ticket?.cr?.[0]
      if (c) {
        expect(BASELINE).toContainEqual({ ref: `cr:${lesson.id}#0`, rev: constructedRev(c) })
        break
      }
    }
  })

  test('an alignment item, an iso break, every protege step, a spiral item and an anchor match the player', () => {
    const align = codeAlignAt(ALL_LESSONS)
    const alignRef = `item:${align.lesson.id}.align.${align.n}`
    expect(BASELINE).toContainEqual({ ref: alignRef, rev: quizRev(align.q) })
    expect(revFor({ source: 'item', item: { id: `${align.lesson.id}.align.${align.n}`, q: align.q, kcs: [] } })).toBe(quizRev(align.q))

    const second = secondAlign(ALL_LESSONS)
    expect(second.n).toBe(2)
    expect(BASELINE).toContainEqual({ ref: `item:${second.lesson.id}.align.2`, rev: quizRev(second.q) })

    let iso: { lesson: Lesson; block: Extract<Lesson['blocks'][number], { type: 'isomorphism' }>; n: number } | null = null
    let protege: { lesson: Lesson; block: Extract<Lesson['blocks'][number], { type: 'protege' }>; n: number } | null = null
    for (const lesson of ALL_LESSONS) {
      let isoN = 0
      let protegeN = 0
      for (const block of lesson.blocks) {
        if (block.type === 'isomorphism') {
          isoN += 1
          if (!iso && block.breakItem) iso = { lesson, block, n: isoN }
        }
        if (block.type === 'protege') {
          protegeN += 1
          if (!protege) protege = { lesson, block, n: protegeN }
        }
      }
    }
    if (!iso) throw new Error('no isomorphism block with a break item')
    if (!protege) throw new Error('no protege block')

    const breakItemPlayed = breakItem(iso.lesson.id, iso.n, iso.block, iso.block.breakItem)
    expect(authoredItemRev(breakItemPlayed.item)).toBe(revFor(breakItemPlayed))
    for (const step of PROTEGE_STEPS) {
      const played = stepItem(protege.lesson.id, protege.n, protege.block, step)
      expect(authoredItemRev(played.item)).toBe(revFor(played))
    }

    const spiral = ALL_LESSONS.flatMap((l) => l.ticket?.spiral ?? [])[0]
    if (!spiral) throw new Error('no spiral item')
    expect(authoredItemRev(spiral)).toBe(revFor({ source: 'item', item: spiral }))
    expect(authoredItemRev(R_ANCHORS[0])).toBe(revFor({ source: 'item', item: R_ANCHORS[0] }))
  })
})

describe('the migration tables', () => {
  test('REF_MIGRATIONS is empty; a row needs every raw reader of e.ref fixed first', () => {
    // `canonicalRef` is applied only in fold.ts:117; resolve.ts (raw e.ref at :160), cards.ts (the card-evidence path at
    // :375 and the quiz lesson ref at :382) and item-block.ts (:97) read the ref as written. A row would therefore
    // credit the aggregate and not the cards. The comment in refs.ts carries the same reason.
    expect(Object.keys(REF_MIGRATIONS)).toEqual([])
  })

  test('KC_MIGRATIONS is empty; resolve.ts applies them, so a row changes which cards an event credits', () => {
    expect(KC_MIGRATIONS).toEqual([])
  })
})
